33	     * year it ends in, e.g. {@code 2027}), hashing the person's {@code normalizedTelephone} and
34	     * {@code lastName} into HASH8 and appending the Luhn check digit over the preceding digits.
35	     */
36	    public static String of(String region, int fiscalYear, String normalizedTelephone, String lastName) {
37	        String body = region + String.format("%02d", fiscalYear % 100)
38	                + hash8(orEmpty(normalizedTelephone) + orEmpty(lastName));
39	        return body + Luhn.checkDigit(body);
40	    }
41	
42	    /**
43	     * De-duplicates {@code memberId} against the ids already {@code taken}: if it is unused it is
44	     * returned unchanged, otherwise {@code '-<n>'} is appended with the smallest {@code n >= 2} that
45	     * yields an id not already taken (e.g. {@code 'NSW271A2B3C4D5'} → {@code 'NSW271A2B3C4D5-2'}).
46	     */
47	    public static String deduplicate(String memberId, Set<String> taken) {
48	        if (!taken.contains(memberId)) {
