12	 * without any sequence number (e.g. {@code 'NSW271A2B3C4D5'}). CHK is the Luhn check digit computed
13	 * over the digits of {@code <REGION><FY><HASH8>}.
14	 */
15	public final class MemberId {
16	
17	    private static final String SEPARATOR = "-";
18	
19	    /** Number of leading hex characters of the digest kept as HASH8. */
20	    private static final int HASH_LENGTH = 8;
21	
22	    /** Number of digits in the FY segment. */
23	    private static final int FISCAL_YEAR_LENGTH = 2;
24	
25	    /** Length of the fixed core following the region: {@code FY(2) + HASH8(8) + CHK(1)}. */
26	    private static final int CORE_SUFFIX_LENGTH = FISCAL_YEAR_LENGTH + HASH_LENGTH + 1;
27	
28	    private MemberId() {
29	    }
30	
31	    /**
32	     * The member id for the given {@code region} and {@code fiscalYear} (identified by the calendar
33	     * year it ends in, e.g. {@code 2027}), hashing the person's {@code normalizedTelephone} and
34	     * {@code lastName} into HASH8 and appending the Luhn check digit over the preceding digits.
35	     */
36	    public static String of(String region, int fiscalYear, String normalizedTelephone, String lastName) {
37	        String body = region + String.format("%02d", fiscalYear % 100)
38	                + hash8(orEmpty(normalizedTelephone) + orEmpty(lastName));
39	        return body + Luhn.checkDigit(body);
40	    }
41	
42	    /**
43	     * De-duplicates {@code memberId} against the ids already {@code taken}: if it is unused it is
44	     * returned unchanged, otherwise {@code '-<n>'} is appended with the smallest {@code n >= 2} that
45	     * yields an id not already taken (e.g. {@code 'NSW271A2B3C4D5'} → {@code 'NSW271A2B3C4D5-2'}).
46	     */
47	    public static String deduplicate(String memberId, Set<String> taken) {
48	        if (!taken.contains(memberId)) {
49	            return memberId;
50	        }
51	        for (int n = 2; ; n++) {
52	            String candidate = memberId + SEPARATOR + n;
53	            if (!taken.contains(candidate)) {
54	                return candidate;
55	            }
56	        }
57	    }
58	
59	    /** The REGION segment of a member id (everything before the fixed {@code <FY><HASH8><CHK>} core). */
60	    public static String region(String memberId) {
61	        String core = beforeSuffix(memberId);
62	        return core.substring(0, core.length() - CORE_SUFFIX_LENGTH);
63	    }
64	
65	    /** The FY segment (2-digit fiscal year) of a member id. */
66	    public static String fiscalYear(String memberId) {
67	        String core = beforeSuffix(memberId);
68	        int start = core.length() - CORE_SUFFIX_LENGTH;
69	        return core.substring(start, start + FISCAL_YEAR_LENGTH);
70	    }
71	
72	    /** The member id without any {@code '-<n>'} de-duplication suffix. */
73	    private static String beforeSuffix(String memberId) {
74	        int separator = memberId.indexOf(SEPARATOR);
75	        return separator < 0 ? memberId : memberId.substring(0, separator);
76	    }
77	
78	    private static String hash8(String source) {
79	        return Sha256.hex(source).substring(0, HASH_LENGTH).toUpperCase(Locale.ROOT);
80	    }
81	
82	    private static String orEmpty(String value) {
83	        return value == null ? "" : value;
84	    }
85	}
