9	 * human-readable audit line for {@code POST /api/owners}. Serialized to a JSON object
10	 * {@code {seq, ownerId, memberId, membershipLevel, event}} where {@code event} is always
11	 * {@code OWNER_CREATED} and {@code seq} is a monotonically increasing sequence across creates.
12	 *
13	 * <p>The event carries the owner's <em>current primary identifier</em>, the {@code memberId},
14	 * resolved in one place ({@link #primaryIdentifier(Owner)}).
15	 */
16	public record OwnerCreatedEvent(long seq, Integer ownerId, String memberId, Integer membershipLevel,
17	        String event) {
18	
19	    private static final String EVENT_TYPE = "OWNER_CREATED";
20	
21	    /** Builds the event for a persisted {@code owner} at the given monotonic {@code seq}. */
22	    public static OwnerCreatedEvent of(long seq, Owner owner) {
23	        return new OwnerCreatedEvent(seq, owner.getId(), primaryIdentifier(owner),
24	                owner.getMembershipLevel(), EVENT_TYPE);
25	    }
26	
27	    /** The owner's current primary identifier, the {@code memberId}. */
28	    private static String primaryIdentifier(Owner owner) {
29	        return owner.getMemberId();
30	    }
31	
32	    /** Renders this event as a JSON object string. */
33	    public String toJson(JsonMapper mapper) {
34	        return mapper.writeValueAsString(this);
35	    }
36	}
