package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.function.owner.OwnerEmail;
import org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity;
import org.springframework.samples.petclinic.rest.function.owner.OwnerTelephone;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
import org.springframework.samples.petclinic.util.AgeBand;
import org.springframework.samples.petclinic.util.MemberId;
import org.springframework.samples.petclinic.util.OwnerRegion;
import org.springframework.samples.petclinic.util.OwnerSegment;
import org.springframework.samples.petclinic.util.RegionTimezone;

import java.util.Collection;
import java.util.List;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
    @Mapping(target = "salutation", expression = "java(salutation(owner))")
    @Mapping(target = "displayName", expression = "java(displayName(owner))")
    @Mapping(target = "initials", expression = "java(initials(owner))")
    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
    @Mapping(target = "locality", expression = "java(locality(owner))")
    @Mapping(target = "timezone", expression = "java(timezone(owner))")
    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
    @Mapping(target = "riskFlag", expression = "java(riskFlag(owner))")
    OwnerDto toOwnerDto(Owner owner);

    /** The owner's canonical relative URL, '/api/owners/' followed by its id. */
    default String selfLink(Owner owner) {
        return "/api/owners/" + owner.getId();
    }

    /** The owner's stored E.164 telephone formatted for people to read (country code, space,
     *  national digits grouped in threes), or null when it is not a recognised E.164 number.
     *  See {@link OwnerTelephone#toDisplay}. */
    default String telephoneDisplay(Owner owner) {
        return OwnerTelephone.toDisplay(owner.getTelephone()).orElse(null);
    }

    /** The owner's name formatted as 'LastName, FirstName' from the stored names. */
    default String displayName(Owner owner) {
        return owner.getLastName() + ", " + owner.getFirstName();
    }

    /** The owner's salutation: the courtesy title followed by a space and the lastName
     *  (e.g. 'DR Franklin'), or just the lastName when no title was supplied. */
    default String salutation(Owner owner) {
        String title = owner.getTitle();
        return title == null || title.isBlank()
                ? owner.getLastName()
                : title + " " + owner.getLastName();
    }

    /** The upper-cased first letters of firstName and lastName, dot-separated with a
     *  trailing dot, e.g. 'J.S.'. */
    default String initials(Owner owner) {
        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
    }

    /** The fiscal year carried by the memberId as 'FY&lt;YY&gt;' (see {@link MemberId}, e.g. 'FY27').
     *  Null when the memberId is absent. */
    default String fiscalYear(Owner owner) {
        return owner.getMemberId() == null ? null : "FY" + MemberId.fiscalYear(owner.getMemberId());
    }

    /** The owner's locality: the REGION segment of its memberId, which is the canonical region the
     *  id was built from. Falls back to deriving the region straight from the postcode and city when
     *  the memberId is absent (so an owner without one still resolves a locality). */
    default String locality(Owner owner) {
        return owner.getMemberId() != null
                ? MemberId.region(owner.getMemberId())
                : OwnerRegion.of(owner.getPostcode(), owner.getCity());
    }

    /** The owner's timezone: the IANA name from the fixed region-to-timezone table
     *  (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne, QLD-&gt;Australia/Brisbane), keyed
     *  off the owner's {@link #locality locality}. Null when the region has no mapped timezone. */
    default String timezone(Owner owner) {
        return RegionTimezone.of(locality(owner));
    }

    /** The owner's preferred contact method: 'EMAIL' when an email address is present,
     *  otherwise 'PHONE'. */
    default String contactPreference(Owner owner) {
        return owner.getEmail() != null && !owner.getEmail().isEmpty() ? "EMAIL" : "PHONE";
    }

    /** The owner's derived duplicate-detection identity key: the SHA-256 hex of the normalized
     *  telephone, lower-cased email and soundex(lastName) joined by '|'. See {@link OwnerIdentity#key}. */
    default String identityKey(Owner owner) {
        return OwnerIdentity.key(owner.getTelephone(), owner.getEmail(), owner.getLastName());
    }

    /** The owner's age band derived from its birthDate against its registrationDate, or null when
     *  either date is absent. See {@link AgeBand}. */
    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
            return null;
        }
        return OwnerDto.AgeBandEnum.fromValue(AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate()));
    }

    /** The owner's marketing segment '&lt;TIER&gt;_&lt;AREA&gt;', derived from its membershipLevel and
     *  {@link #locality locality}. See {@link OwnerSegment}. */
    default OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
        return OwnerDto.OwnerSegmentEnum.fromValue(OwnerSegment.of(owner.getMembershipLevel(), locality(owner)));
    }

    /** Whether the owner should be treated as elevated-risk: true when it is a possible
     *  duplicate, its email domain is disposable-adjacent, or its city was over soft capacity
     *  at creation (the {@code capacityWarning}); false otherwise. Each condition reuses state
     *  already derived elsewhere in the owner pipeline. */
    default boolean riskFlag(Owner owner) {
        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
                || Boolean.TRUE.equals(owner.getCapacityWarning())
                || OwnerEmail.isDisposableAdjacent(owner.getEmail());
    }

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

